macro_rules! deps {
    () => {
        Note!();
        Error!();
        Key!();
    };
}

macro_rules! key {
    () => {
        deps!();
        # [doc = ""] pub mod key { use crate :: bstr :: BString ; const fn prefix (kind : char) -> & 'static str { match kind { 'n' => "" , 'k' => "The value of key" , 't' => "The date format at key" , 'i' => "The timeout at key" , 'd' => "The duration [ms] at key" , 'b' => "The boolean at key" , 'v' => "The key" , 'r' => "The refspec at" , 's' => "The ssl version at" , 'u' => "The url at" , 'w' => "The utf-8 string at" , _ => panic ! ("BUG: invalid prefix kind - add a case for it here") , } } const fn suffix (kind : char) -> & 'static str { match kind { 'd' => "could not be decoded" , 'i' => "was invalid" , 'u' => "could not be parsed as unsigned integer" , 'p' => "could not be parsed" , _ => panic ! ("BUG: invalid suffix kind - add a case for it here") , } } # [doc = " A generic error suitable to produce decent messages for all kinds of configuration errors with config-key granularity."] # [doc = ""] # [doc = " This error is meant to be reusable and help produce uniform error messages related to parsing any configuration key."] # [derive (Debug , thiserror :: Error)] # [error ("{} \"{key}{}\"{} {}" , prefix (PREFIX) , value . as_ref () . map (| v | format ! ("={v}")) . unwrap_or_default () , environment_override . as_deref () . map (| var | format ! (" (possibly from {var})")) . unwrap_or_default () , suffix (SUFFIX))] pub struct Error < E : std :: error :: Error + Send + Sync + 'static , const PREFIX : char , const SUFFIX : char > { # [doc = " The configuration key that contained the value."] pub key : BString , # [doc = " The value that was assigned to `key`."] pub value : Option < BString > , # [doc = " The associated environment variable that would override this value."] pub environment_override : Option < & 'static str > , # [doc = " The source of the error if there was one."] pub source : Option < E > , } # [doc = " Initialization"] # [doc = " Instantiate a new error from the given `key`."] # [doc = ""] # [doc = " Note that specifics of the error message are defined by the `PREFIX` and `SUFFIX` which is usually defined by a typedef."] impl < T , E , const PREFIX : char , const SUFFIX : char > From < & 'static T > for Error < E , PREFIX , SUFFIX > where E : std :: error :: Error + Send + Sync + 'static , T : super :: tree :: Key , { fn from (key : & 'static T) -> Self { Error { key : key . logical_name () . into () , value : None , environment_override : key . environment_override () , source : None , } } } # [doc = " Initialization"] impl < E , const PREFIX : char , const SUFFIX : char > Error < E , PREFIX , SUFFIX > where E : std :: error :: Error + Send + Sync + 'static , { # [doc = " Instantiate an error with all data from `key` along with the `value` of the key."] pub fn from_value (key : & 'static impl super :: tree :: Key , value : BString) -> Self { Error :: from (key) . with_value (value) } } # [doc = " Builder"] impl < E , const PREFIX : char , const SUFFIX : char > Error < E , PREFIX , SUFFIX > where E : std :: error :: Error + Send + Sync + 'static , { # [doc = " Attach the given `err` as source."] pub fn with_source (mut self , err : E) -> Self { self . source = Some (err) ; self } # [doc = " Attach the given `value` as value we observed when the error was produced."] pub fn with_value (mut self , value : BString) -> Self { self . value = Some (value) ; self } } # [doc = " A generic key error for use when it doesn't seem worth it say more than 'key is invalid' along with meta-data."] pub type GenericError < E = gix_config :: value :: Error > = Error < E , 'k' , 'i' > ; # [doc = " A generic key error which will also contain a value."] pub type GenericErrorWithValue < E = gix_config :: value :: Error > = Error < E , 'v' , 'i' > ; }
    };
}

key!();